from lib import *
M=mcq;F=tf;S=short;N=num
chapter(4,'maths','the-cleanest-village','The Cleanest Village',
 ('A school trip','Daisy and Lou of Shillong are going on a school trip to Mawlynnong, called Asia\'s cleanest village, 79 km from Shillong. The trip costs 500 rupees per child, the bus leaves school at 7 am and returns at 4 pm. Before the trip the family goes shopping, and Daisy and Lou practise money sums at the vegetable cart and the store.'),
 [('The trip poster',['Mawlynnong is in the East Khasi Hills, 79 km from Shillong. About 77 Khasi families, or 414 people, live there.','Children see the Living Root Bridge, a waterfall and a church, and enjoy sightseeing, rich culture and nature.','Everyone must carry a hat, a water bottle and lunch. The bus leaves at 7 am and returns at 4 pm.']),
  ('Shopping with prices',['Sapan Dada sells at a cart. Per kilogram: custard apple 45 rupees, beans 95, radish 23, potato 37, yam 45, sapota 70, papaya 65 and banana 55.','For 2 kg of beans we add 95 and 95 to get 190 rupees.','1 kg custard apple and 1 kg sapota cost 45 + 70 = 115 rupees. We can use a number line or play money to add.','Their mother buys things for 163 rupees. There is more than one possible set of things, so try making 163 from several prices.']),
  ('Giving the balance',['At Udaya Didi\'s store the customer pays and we return the balance.','Balance = amount paid minus cost. If the cost is 113 and the customer pays 150, the balance is 37 rupees.','If the cost is 185 and the customer pays 200, the balance is 15 rupees, and if the cost is 435 and they pay 500, the balance is 65 rupees.','We can count up from the cost to the amount paid, like a shopkeeper, using a number line or play money.'])],
 [('The cost is 435 rupees and the customer pays 500 rupees. What is the balance?',[('Balance = paid minus cost = 500 - 435.','Subtract the cost from the money paid.'),('435 + 5 = 440, 440 + 60 = 500, so 5 + 60 = 65 rupees.','Counting up from the cost is a shopkeeper\'s way.')]),
  ('What is the cost of 2 kg of beans and 1 kg of custard apple?',[('2 kg of beans = 95 + 95 = 190 rupees.','Add the price twice.'),('Add custard apple 45: 190 + 45 = 235 rupees.','Then add the other cost.')])],
 ('Explain how to find the balance when you pay more than the cost.',['Balance = paid - cost','Count up from the cost','Use a number line or play money'],['Balance means cost plus paid']),
 ['Mawlynnong is Asia\'s cleanest village, in East Khasi Hills.','Add prices to find a total cost.','Balance = amount paid - cost.'],
 [N('1',1,'What is the balance when the cost is 113 and you pay 150?',37,'150 - 113 = 37 rupees.',[(263,'You added instead of subtracting')],'rupees'),
  N('2',1,'2 kg of beans cost 95 rupees per kg. What is the total cost?',190,'95 + 95 = 190.',[(95,'That is the cost of 1 kg')],'rupees'),
  F('3',1,'The school bus leaves school at 7 am for the trip.',True,'The poster says departure from school at 7 am.'),
  N('4',2,'1 kg custard apple (45) and 1 kg sapota (70) together cost?',115,'45 + 70 = 115.',[(25,'You subtracted')],'rupees'),
  N('5',2,'Cost 435, paid 500. What is the balance?',65,'500 - 435 = 65.',[(935,'You added instead')],'rupees'),
  M('6',2,'How far is Mawlynnong from Shillong?','79 km',[('7 km','Much farther'),('414 km','That is the population')],'The poster says 79 km from Shillong.'),
  S('7',3,'Cost 185, paid 200. What is the balance? (number only)',['15'],'200 - 185 = 15.'),
  M('8',3,'What does the shopkeeper return to the customer?','The balance',[('The cost','The customer pays the cost'),('The price list','Not money')],'The balance is the extra money paid.')])
chapter(4,'maths','weigh-it-pour-it','Weigh It, Pour It',
 ('At the vegetable market','Rita and Shabnam went to the market and saw the seller weighing vegetables. In Class 3 we learned about the 1 kilogram salt packet and the 1 litre bottle. Now we find out more about kilograms and grams.'),
 [('Heavy and light',['We can arrange animals or objects from heaviest to lightest by comparing their weights.','We know how heavy something is by lifting it, or better, by weighing it. A bag that is heavy is carried with some effort.']),
  ('Estimating and weighing',['Before weighing, we estimate whether something is less than 1 kg or more than 1 kg, such as 6 bananas, 5 potatoes, 10 tomatoes or 15 onions.','Then we check by weighing on a balance and note the actual weight.','Guessing and then checking makes our estimates better.']),
  ('Kilograms and grams',['We write kg for kilogram and g for gram, and 1 kg is 1000 g.','Two packets of 500 g make 1000 g, which is 1 kg, so 500 g is half a kilogram.','Four packets of 250 g make 1 kg, so 250 g is one quarter of a kilogram.','Ten packets of 100 g also make 1 kg.','Two 250 g packets balance one 500 g packet on a balance.'])],
 [('How many 250 g packets balance one 500 g packet?',[('500 g is 2 packets of 250 g because 250 + 250 = 500.','Add the packets.'),('So two 250 g packets balance one 500 g packet; 250 g is half of 500 g.','The pans are equal.')]),
  ('How many 100 g packets make 1 kg?',[('1 kg = 1000 g.','Convert to grams.'),('1000 divided by 100 is 10, so ten packets.','Divide into equal packets.')])],
 ('Explain how kilograms and grams are related with packet examples.',['1 kg = 1000 g','500 g = 1/2 kg','250 g = 1/4 kg'],['1 kg = 100 g']),
 ['1 kg = 1000 g.','500 g is half a kg and 250 g is a quarter of a kg.','Estimate, then weigh to check.'],
 [N('1',1,'How many grams make 1 kg?',1000,'1 kg is 1000 g.',[(100,'That is too small')],'g'),
  M('2',1,'500 g is what part of 1 kg?','Half',[('Quarter','250 g is a quarter'),('Whole','1000 g is a whole')],'Two 500 g packets make 1 kg, so 500 g is half a kg.'),
  F('3',1,'Four packets of 250 g make 1 kg.',True,'4 x 250 g = 1000 g = 1 kg.'),
  N('4',2,'How many 100 g packets make 1 kg?',10,'1000 divided by 100 is 10.',[(100,'Not 100')]),
  M('5',2,'Which balances a 500 g packet?','Two 250 g packets',[('One 250 g packet','Too light'),('Four 250 g packets','Too heavy')],'250 + 250 = 500.'),
  S('6',2,'What do we write for kilogram?',['kg'],'kg stands for kilogram, g stands for gram.'),
  F('7',3,'We should guess the weight and then check with a balance.',True,'Estimating and checking improves our judgement.'),
  N('8',3,'3 packets of 250 g together weigh how many grams?',750,'250 + 250 + 250 = 750 g.',[(500,'That is two packets')],'g')])
